window.ATLAS_RULES = {"difficulty_ladder": [{"label": "Very Easy", "dc": 5, "use": "Obvious, low-pressure, or strong fictional leverage."}, {"label": "Easy", "dc": 10, "use": "Clear action, low pressure, or good fictional leverage."}, {"label": "Average", "dc": 15, "use": "Meaningful uncertainty under pressure."}, {"label": "Hard", "dc": 20, "use": "Dangerous, rushed, opposed, or magically unstable."}, {"label": "Very Hard", "dc": 25, "use": "Exceptional, unstable, or specialized."}, {"label": "Nearly Impossible", "dc": 30, "use": "Legendary attempt; usually offer another route."}], "outcome_guide": ["Critical success: give the clean result plus momentum, extra truth, or a concrete boon.", "Success with Hope: success and one generous detail, question, or advantage.", "Success with Fear: success, but expose cost, split attention, tick a countdown, or reveal a future complication.", "Failure with Hope: miss the full goal, but reveal a useful truth or preserve agency.", "Failure with Fear: make a GM move that follows from the fiction and leaves the next choice clear."], "fear_spends": ["Advance the ritual or relay countdown.", "Separate a protector from the Keystone or Custodian.", "Reveal a corporate cost or omitted clause.", "Escalate environmental pressure instead of adding a random enemy.", "Offer a hard bargain that protects people at a cost.", "Activate Market Correction, Pass-Through, Ambush, or Group Attack when the scene supports it."], "conditions": [{"name": "Vulnerable", "note": "Make the character feel exposed before applying the mechanical tag."}, {"name": "Restrained", "note": "Name what binds them and what they can still do."}, {"name": "Hidden", "note": "Confirm foes cannot see or locate the target before applying it."}], "reminders": ["Spotlight combat through visible danger, not initiative bookkeeping.", "Short rest: ask what care looks like, who helps, and what resource is actually recovered.", "Countdown die: announce what changes when it ticks so players can plan around it.", "No lore dump: let forms, wounds, signs, and local reactions carry the system."]};
window.ATLAS_HANDOUTS = [{"id": "premise", "title": "Player-Safe Premise", "tags": ["Player-safe", "Print-ready", "TV-safe"], "body": "You are contractors or trusted associates delivering a sealed package through Sablewood to Hush. Marlowe Fairwind is a playable pregen and the default package custodian; Sabine Quillon is only an optional backup NPC contact for the S00-01 job scene. The job begins inside the system, not outside it."}, {"id": "contract", "title": "Goldspire Delivery Contract", "tags": ["Player-safe", "Print-ready"], "body": "Route assurance contract for sealed ward-related cargo. Liability language is optimistic; the missing risks are the point."}, {"id": "incident-placard", "title": "Incident Response Placard", "tags": ["Player-safe", "Print-ready"], "body": "If found, preserve cargo value, identify reimbursable losses, and await authorized incident classification."}, {"id": "route-ledger", "title": "Route Ledger", "tags": ["Player-safe", "Print-ready", "Spoilers"], "body": "The ledger times do not match the official route. Someone altered the logistics trail before the cart was found."}, {"id": "bramble-slips", "title": "Bramble Evidence Slips", "tags": ["GM-only", "Print-ready", "Spoilers"], "body": "Signal knots, old road-crew tags, charm-stone armor, and a route sketch reveal grievance without excusing murder."}, {"id": "hush-welcome", "title": "Hush Welcome Card", "tags": ["Player-safe", "TV-safe"], "body": "Welcome to Hush. Shoes off at the Co-op. If your boots are returned cleaner than you left them, say thank you twice."}, {"id": "clover-gifts", "title": "Clover Co-op Gift Table", "tags": ["Player-safe", "Print-ready"], "body": "Warm rolls, moss-honey, clover cord bracelet, safe-path directions, antiseptic moss, and a quiet warning about the Custodian."}, {"id": "keystone-warning", "title": "Keystone Warning Label", "tags": ["Player-safe", "Print-ready", "Spoilers"], "body": "Do not open near unstable ward lines. Do not strike. Do not cast strong magic within arm's reach unless a keeper says the stone is listening."}, {"id": "open-vale-reference", "title": "Open Vale Ritual Reference", "tags": ["GM-only", "Print-ready", "Spoilers"], "body": "Protect the Custodian, hold the ward lines, track the countdown, and spend Fear when old obligations answer the ritual."}, {"id": "gm-quick-sheet", "title": "GM Quick Sheet", "tags": ["GM-only", "Print-ready"], "body": "Very Easy 5, Easy 10, Average 15, Hard 20, Very Hard 25, Nearly Impossible 30. On Fear, make risk visible before making it worse. Spend Fear to split attention, threaten cargo, advance countdowns, expose costs, or activate environment pressure."}, {"id": "conditions", "title": "Condition / Hope / Fear Cheat Sheet", "tags": ["Player-safe", "Print-ready", "TV-safe"], "body": "Hope improves position, reveals a clean truth, or gives a boon. Fear succeeds with cost, invites a move, or advances a visible threat. The official global conditions are Hidden, Restrained, and Vulnerable."}];
